import { Button } from '@/components/ui/button';
import { RocketIcon } from '@radix-ui/react-icons';

export default function NotFound() {
  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-900 via-purple-900 to-violet-800 p-8 flex items-center justify-center">
      <div className="relative max-w-4xl mx-auto">
        {/* Glass morphism container */}
        <div className="backdrop-blur-lg bg-white/10 rounded-3xl p-12 shadow-2xl shadow-purple-500/20 border border-white/20 overflow-hidden">
          {/* Decorative elements */}
          <div className="absolute -top-20 -right-20 w-64 h-64 bg-purple-500/30 rounded-full filter blur-3xl"></div>
          <div className="absolute -bottom-20 -left-20 w-64 h-64 bg-indigo-500/30 rounded-full filter blur-3xl"></div>
          
          {/* Content */}
          <div className="relative z-10 text-center">
            <div className="inline-flex items-center justify-center bg-white/10 p-6 rounded-full mb-8">
              <svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-white">
                <circle cx="12" cy="12" r="10"></circle>
                <line x1="4.93" y1="4.93" x2="19.07" y2="19.07"></line>
              </svg>
            </div>
            
            <h1 className="text-6xl font-bold text-white mb-4">404</h1>
            <h2 className="text-2xl font-semibold text-white/90 mb-6">Page Not Found</h2>
            <p className="text-lg text-white/80 max-w-lg mx-auto mb-8">
              Oops! The page you're looking for doesn't exist or has been moved. Let's get you back on track.
            </p>
            
            <div className="flex gap-4 justify-center">
              <Button className="bg-white text-indigo-900 hover:bg-white/90 px-8 py-6 text-lg rounded-xl">
                <RocketIcon className="mr-2 h-5 w-5" /> Go Home
              </Button>
              <Button variant="outline" className="text-white border-white hover:bg-white/10 px-8 py-6 text-lg rounded-xl">
                Contact Support
              </Button>
            </div>
          </div>
        </div>
        
        {/* Stats widget */}
        <div className="mt-8 grid grid-cols-3 gap-4">
          {['Visitors', 'Pages', 'Resources'].map((item) => (
            <div key={item} className="backdrop-blur-md bg-white/5 rounded-xl p-4 text-center border border-white/10">
              <p className="text-sm text-white/60 mb-1">{item}</p>
              <p className="text-2xl font-bold text-white">1,024</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}